def apply(inputs, premises):
    lengths = inputs["lengths"]
    widths = inputs["widths"]
    heights = inputs["heights"]
    weights = inputs["weights"]
    personal = inputs["personal_dimension_limits"]
    carryon = inputs["carryon_dimension_limits"]
    checked = []
    personal_used = False
    carryon_used = False
    for i in range(len(lengths)):
        fits_personal = lengths[i] <= personal[0] and widths[i] <= personal[1] and heights[i] <= personal[2]
        fits_carryon = lengths[i] <= carryon[0] and widths[i] <= carryon[1] and heights[i] <= carryon[2]
        if fits_personal and not personal_used:
            personal_used = True
        elif fits_carryon and not carryon_used:
            carryon_used = True
        else:
            checked = checked + [i]
    checked_count = len(checked)
    base_total = sum(inputs["base_fees_by_checked_position"][:checked_count])
    complimentary_count = 0
    for fee in inputs["base_fees_by_checked_position"][:checked_count]:
        if fee == 0:
            complimentary_count = complimentary_count + 1
    complimentary_count = min(complimentary_count, checked_count)
    charged_excess_total = 0
    savings = []
    for checked_position in range(checked_count):
        i = checked[checked_position]
        dimension = lengths[i] + widths[i] + heights[i]
        charged_weight_fee = 0
        if weights[i] > inputs["charged_weight_limit"]:
            for j in range(len(inputs["overweight_upper_limits"])):
                if weights[i] <= inputs["overweight_upper_limits"][j]:
                    charged_weight_fee = inputs["overweight_fees"][j]
                    break
        complimentary_weight_fee = 0
        if weights[i] > inputs["complimentary_weight_limit"]:
            for j in range(len(inputs["overweight_upper_limits"])):
                if weights[i] <= inputs["overweight_upper_limits"][j]:
                    complimentary_weight_fee = inputs["overweight_fees"][j]
                    break
        size_fee = 0
        if dimension > inputs["standard_dimension_limit"]:
            for j in range(len(inputs["oversize_upper_limits"])):
                if dimension <= inputs["oversize_upper_limits"][j]:
                    size_fee = inputs["oversize_fees"][j]
                    break
        charged_excess = max(charged_weight_fee, size_fee)
        complimentary_excess = max(complimentary_weight_fee, size_fee)
        charged_excess_total = charged_excess_total + charged_excess
        savings = savings + [charged_excess - complimentary_excess]
    ordered_savings = sorted(savings)
    complimentary_savings = sum(ordered_savings[len(ordered_savings) - complimentary_count:])
    total = inputs["ticket_price"] + base_total + charged_excess_total - complimentary_savings
    return {"answer": int(total)}

